    <script>
      (function() {
        if (window.document.documentMode) {
          function getCookie(cname) {
            let name = cname + "=";
            let decodedCookie = decodeURIComponent(document.cookie);
            let ca = decodedCookie.split(';');
            for(let i = 0; i <ca.length; i++) {
              let c = ca[i];
              while (c.charAt(0) == ' ') {
                c = c.substring(1);
              }
              if (c.indexOf(name) == 0) {
                return c.substring(name.length, c.length);
              }
            }
            return "";
          }

          function getLanguageCookie() {
            return getCookie('language');
          }

          function getNavigatorLanguage() {
            if (!String.prototype.startsWith) {
              Object.defineProperty(String.prototype, 'startsWith', {
                value: function(search, rawPos) {
                  var pos = rawPos > 0 ? rawPos|0 : 0;
                  return this.substring(pos, pos + search.length) === search;
                }
              });
            }

            var language = navigator.language || navigator.userLanguage || '';
            if (language.startsWith('de')) return 'de';
            if (language.startsWith('fr')) return 'fr';
            if (language.startsWith('it')) return 'it';
            if (language.startsWith('en')) return 'en';
          }

          function getUrl(language) {
            if (language === 'de') return '/de/support/services/systemanforderungen/betriebssysteme-browser.html';
            if (language === 'fr') return '/fr/assistance/exigences-systeme/navigateur-systeme.html';
            if (language === 'it') return '/it/assistenza/requisiti-di-sistema/sistemi-operativi-browser.html';
            if (language === 'en') return '/en/support/system-requirements/os-browsers.html';
          }

          window.location.href = getUrl(getLanguageCookie() || getNavigatorLanguage() || 'de');
        }
      })()
    </script>
